export const katakana=s=>[...s].map(c=>c>='ぁ'&&c<='ゖ'?String.fromCharCode(c.charCodeAt(0)+96):c).join('');
export const kanaRows=hira.map((r,i)=>[...r].map((h,j)=>h===' '?null:{h,k:katakana(h),r:roma[i].split(' ')[j],example:examples[h],group:i<11?'basic':'voiced'}));
const combos=[['き','ky'],['し','sh'],['ち','ch'],['に','ny'],['ひ','hy'],['み','my'],['り','ry'],['ぎ','gy'],['じ','j'],['び','by'],['ぴ','py']];
export const comboRows=combos.map(([h,r])=>['ゃ','ゅ','ょ'].map((y,i)=>({h:h+y,k:katakana(h+y),r:r+['a','u','o'][i],group:'combo'})));
export const allWords=lessons.flatMap(l=>l.words.map(w=>({...w,lesson:l.id})));
